import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport,
  validateThresholds,
  evaluateThresholds
} from './index.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('validates thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const validThresholds = { exact_match: 0.5, toxicity: 0.8 };
    const validation = validateThresholds(validThresholds, evaluations);
    expect(validation.valid).toBe(true);

    const invalidMetric = { nonexistent_metric: 0.5 };
    const validation2 = validateThresholds(invalidMetric, evaluations);
    expect(validation2.valid).toBe(false);
    expect(validation2.errors.length).toBeGreaterThan(0);

    const invalidValue = { exact_match: 1.5 };
    const validation3 = validateThresholds(invalidValue, evaluations);
    expect(validation3.valid).toBe(false);
    expect(validation3.errors.length).toBeGreaterThan(0);
  });

  it('evaluates thresholds against metrics', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const thresholds = { exact_match: 0.5 };
    const result = evaluateThresholds(evaluations, thresholds);

    expect(result.passed).toBe(true);
    expect(result.thresholds.length).toBe(1);
    expect(result.thresholds.every((t) => t.passed)).toBe(true);
  });

  it('fails thresholds when score is below minimum', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const thresholds = { exact_match: 0.99 };
    const result = evaluateThresholds(evaluations, thresholds);

    expect(result.passed).toBe(false);
    expect(result.thresholds[0].passed).toBe(false);
  });

  it('fails threshold for metric with no score', () => {
    const evaluations = [
      {
        id: 'no_score_metric',
        label: 'No Score Metric',
        score: null,
        total: 1
      }
    ];

    const thresholds = { no_score_metric: 0.5 };
    const result = evaluateThresholds(evaluations, thresholds);

    expect(result.passed).toBe(false);
    expect(result.thresholds[0].passed).toBe(false);
    expect(result.thresholds[0].score).toBe(null);
  });

  it('includes thresholds in generated report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const thresholds = { exact_match: 0.5, toxicity: 0.8 };
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toBeDefined();
    expect(report.thresholds.length).toBe(2);
    expect(report.thresholds[0]).toHaveProperty('metric');
    expect(report.thresholds[0]).toHaveProperty('min');
    expect(report.thresholds[0]).toHaveProperty('score');
    expect(report.thresholds[0]).toHaveProperty('passed');
  });

  it('does not include thresholds when not provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });

    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });
});

