477	function parseThresholds(thresholdArgs?: string[]): Record<string, number> | undefined {
478	  if (!thresholdArgs || thresholdArgs.length === 0) {
479	    return undefined;
480	  }
481	
482	  const thresholds: Record<string, number> = {};
483	
484	  for (const arg of thresholdArgs) {
485	    const match = arg.match(/^([^=]+)=(.+)$/);
486	    if (!match) {
487	      throw new Error(`Malformed threshold: ${arg}. Expected format: <metric>=<number>`);
488	    }
489	
490	    const [, metricId, valueStr] = match;
491	    const value = Number.parseFloat(valueStr);
492	
493	    if (!Number.isFinite(value) || value < 0 || value > 1) {
494	      throw new Error(
495	        `Invalid threshold value for ${metricId}: ${valueStr}. Must be a number between 0 and 1.`
496	      );
497	    }
498	
499	    thresholds[metricId] = value;
500	  }
501	
502	  return thresholds;
503	}
504	
505	function runEvalCommand(options: EvalOptions) {
506	  assertFileExists(options.outputs);
507	
508	  let thresholds: Record<string, number> | undefined;
509	  try {
510	    thresholds = parseThresholds(options.threshold);
511	  } catch (error) {
512	    log.error((error as Error).message);
513	    process.exit(2);
514	  }
515	
516	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
517	    outputsPath: options.outputs,
518	    referencesPath: options.references
519	  });
520	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
521	    outputs: dataset.outputs,
522	    references: dataset.references
523	  });
524	
525	  if (thresholds) {
526	    const validation = (Eval.validateThresholds as unknown as (metrics: unknown, thresholds: unknown) => any)(
527	      evaluations,
528	      thresholds
529	    );
530	    if (!validation.valid) {
531	      log.error('Threshold validation failed:');
532	      validation.errors.forEach((error: string) => {
533	        console.error(` - ${error}`);
534	      });
535	      process.exit(2);
536	    }
537	  }
538	
539	  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
540	    evaluations,
541	    outputsPath: dataset.outputsPath,
542	    referencesPath: dataset.referencesPath,
543	    thresholds
544	  });
545	  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
546	    report,
547	    format: options.format ?? 'json',
548	    reportPath: options.report
549	  });
550	  log.success('Evaluation report generated.', { path: resolvedPath });
551	
552	  if (thresholds && report.passed === false) {
553	    process.exit(1);
554	  }
555	}
