557	function runRagIndexCommand(options: RagOptions) {
558	  const payload = (Rag.indexDocuments as unknown as (config: unknown) => any)({
559	    input: options.input,
560	    output: options.output,
561	    chunkSize: options.chunkSize,
562	    extensions: options.extensions
563	  });
564	  log.success('RAG index created.', {
565	    documentCount: payload.metadata.documentCount,
566	    entryCount: payload.metadata.entryCount,
567	    output: options.output ?? 'frai-index.json'
568	  });
569	}
