const dataset = Eval.loadDataset({
  outputsPath: './outputs.json',
  referencesPath: './references.json'
});

const evaluations = Eval.runEvaluations({
  outputs: dataset.outputs,
  references: dataset.references
});

// Validate thresholds before generating report
const thresholds = { exact_match: 0.9, length_variance: 0.7 };
const validation = Eval.validateThresholds(evaluations, thresholds);
if (!validation.valid) {
  console.error('Invalid thresholds:', validation.errors);
  process.exit(2);
}

// Generate report with thresholds
const report = Eval.generateReport({
  evaluations,
  outputsPath: dataset.outputsPath,
  referencesPath: dataset.referencesPath,
  thresholds
});

// Write report (includes threshold outcomes)
const reportPath = Eval.writeReport({
  report,
  format: 'json',
  reportPath: './eval-report.json'
});

// Exit with code 1 if any threshold failed (for CI gating)
if (!report.passed) {
  process.exit(1);
}
